// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { Btn, DemoStage, PanelChrome, highlight, type Build } from '@/app/demos/stage'

import { CAPTIONS, JSON_OUT, XML_LINES, XML_MIN } from './script'

const INDENT = 14

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  const swap = (from: string, to: string) => {
    tl.to(q(from), { opacity: 0, duration: 0.22 })
    tl.set(q(to), { opacity: 1 })
  }

  step(0)
  move('editor', { at: 0.3, ax: 0.2, ay: 0.2 })
  click('editor')
  type('min', XML_MIN, { speed: 0.01 })
  tl.to(
    q('status'),
    { color: '#34d399', borderColor: 'rgba(52,211,153,0.5)', duration: 0.2 },
    '+=0.05',
  )
  tl.to(q('status'), { text: 'Valid XML', duration: 0.01 })

  step(1, '+=0.35')
  move('beautify')
  click('beautify')
  swap('min', 'formatted')
  tl.fromTo(
    qa('xml-line'),
    { x: (index) => -XML_LINES[index][0] * INDENT, opacity: 0.35 },
    { x: 0, opacity: 1, duration: 0.55, stagger: 0.05, ease: 'expo.out' },
    '<',
  )

  step(2, '+=0.45')
  move('minify')
  click('minify')
  swap('formatted', 'min')
  tl.fromTo(q('min'), { opacity: 0.4 }, { opacity: 1, duration: 0.3 }, '<')

  step(3, '+=0.4')
  move('json')
  click('json')
  swap('min', 'json-out')
  tl.fromTo(
    qa('json-line'),
    { opacity: 0, x: 10 },
    { opacity: 1, x: 0, duration: 0.28, stagger: 0.04 },
    '<',
  )
  cursorOut('+=0.2')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="XML Toolkit validating, beautifying, minifying and converting XML to JSON"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome
        aside={
          <span
            data-d="status"
            className="rounded-full border border-line-strong px-2.5 py-1 font-mono text-[10px] text-muted"
          >
            —
          </span>
        }
      >
        <div className="flex h-full flex-col gap-3">
          <div
            data-d="editor"
            className="relative min-h-0 flex-1 overflow-hidden rounded-xl border border-line bg-canvas/80 font-mono text-[10.5px] md:text-[11px]"
          >
            <p
              data-d="min"
              className="demo-caret absolute inset-3 break-all leading-[18px] text-ink-soft"
            />
            <div data-d="formatted" className="absolute inset-3 opacity-0">
              {XML_LINES.map(([depth, line], index) => (
                <p
                  key={index}
                  data-d="xml-line"
                  className="h-[18px] whitespace-pre md:h-[19px]"
                  style={{ paddingLeft: depth * INDENT }}
                >
                  {highlight(line)}
                </p>
              ))}
            </div>
            <div
              data-d="json-out"
              className="absolute inset-3 overflow-auto opacity-0 font-mono text-[10px] leading-[16px] text-ink-soft md:text-[10.5px]"
            >
              {JSON_OUT.split('\n').map((line, index) => (
                <p key={index} data-d="json-line" className="whitespace-pre">
                  {line}
                </p>
              ))}
            </div>
          </div>
          <div className="flex flex-wrap gap-2">
            <Btn d="beautify" primary>
              Beautify
            </Btn>
            <Btn d="minify">Minify</Btn>
            <Btn d="json">Convert to JSON</Btn>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
